CREATE TABLE IF NOT EXISTS accounts(id uuid PRIMARY KEY, firebase_uid text UNIQUE NOT NULL, email text NOT NULL, role text NOT NULL CHECK(role IN ('athlete','admin')), created_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz);
CREATE TABLE IF NOT EXISTS athletes(id uuid PRIMARY KEY, owner_id uuid NOT NULL REFERENCES accounts(id), kind text NOT NULL CHECK(kind IN ('self','junior')), name text NOT NULL, dob date NOT NULL, gender text NOT NULL, state text NOT NULL, city text NOT NULL, phone text NOT NULL, guardian_name text, guardian_relationship text, consent_at timestamptz, is_public boolean NOT NULL DEFAULT false, photo_url text, academy text, coach text, goal text, created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS one_self_profile ON athletes(owner_id) WHERE kind='self';
CREATE TABLE IF NOT EXISTS athlete_sports(athlete_id uuid NOT NULL REFERENCES athletes(id) ON DELETE CASCADE, sport text NOT NULL CHECK(sport IN ('Badminton','Tennis','Pickleball')), level text NOT NULL, years integer NOT NULL CHECK(years>=0), primary_sport boolean NOT NULL DEFAULT false, categories jsonb NOT NULL DEFAULT '[]', rankings jsonb NOT NULL DEFAULT '[]', PRIMARY KEY(athlete_id,sport));
CREATE TABLE IF NOT EXISTS ranking_reviews(id uuid PRIMARY KEY, athlete_id uuid NOT NULL REFERENCES athletes(id) ON DELETE CASCADE, sport text NOT NULL, scope text NOT NULL CHECK(scope IN ('state','national')), status text NOT NULL CHECK(status IN ('verified','rejected')), source_snapshot jsonb NOT NULL, reason text NOT NULL, admin_id uuid NOT NULL REFERENCES accounts(id), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(athlete_id,sport,scope));
CREATE TABLE IF NOT EXISTS events(id uuid PRIMARY KEY, name text NOT NULL, sport text NOT NULL CHECK(sport IN ('Badminton','Tennis','Pickleball')), city text NOT NULL, state text NOT NULL, venue text NOT NULL, starts_at timestamptz NOT NULL, ends_at timestamptz NOT NULL, registration_deadline timestamptz NOT NULL, age_cutoff date NOT NULL, withdrawal_deadline timestamptz NOT NULL, refund_policy text NOT NULL, rules text NOT NULL, poster_url text, status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','published','closed','completed','cancelled')), created_by uuid NOT NULL REFERENCES accounts(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS categories(id uuid PRIMARY KEY, event_id uuid NOT NULL REFERENCES events(id), name text NOT NULL, entry_type text NOT NULL CHECK(entry_type IN ('singles','doubles')), format text NOT NULL CHECK(format IN ('knockout','round_robin')), capacity integer NOT NULL CHECK(capacity>=2), fee integer NOT NULL CHECK(fee>=0), min_age integer NOT NULL DEFAULT 0, max_age integer NOT NULL DEFAULT 100, gender text NOT NULL DEFAULT 'any', levels jsonb NOT NULL DEFAULT '[]', best_of integer NOT NULL DEFAULT 3, school_required boolean NOT NULL DEFAULT false, points jsonb NOT NULL DEFAULT '{"winner":400,"runner":250,"semi":150,"participation":40}', draw_published boolean NOT NULL DEFAULT false);
CREATE TABLE IF NOT EXISTS entries(id uuid PRIMARY KEY, category_id uuid NOT NULL REFERENCES categories(id), owner_id uuid NOT NULL REFERENCES accounts(id), status text NOT NULL CHECK(status IN ('partner_pending','awaiting_payment','expired','awaiting_verification','needs_review_no_seat','confirmed','payment_rejected','withdrawal_requested','withdrawn','cancelled')), fee integer NOT NULL, reservation_expires_at timestamptz, invite_token text UNIQUE, invite_expires_at timestamptz, emergency_contact text NOT NULL, school text, rules_accepted_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), idempotency_key text NOT NULL, UNIQUE(owner_id,idempotency_key));
CREATE TABLE IF NOT EXISTS entry_members(entry_id uuid NOT NULL REFERENCES entries(id) ON DELETE CASCADE, athlete_id uuid NOT NULL REFERENCES athletes(id), accepted_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(entry_id,athlete_id));
CREATE TABLE IF NOT EXISTS payments(id uuid PRIMARY KEY, entry_id uuid NOT NULL REFERENCES entries(id), reference text UNIQUE NOT NULL, payer_name text NOT NULL, paid_at timestamptz NOT NULL, amount integer NOT NULL, mode text NOT NULL CHECK(mode IN ('test','live')), status text NOT NULL CHECK(status IN ('submitted','confirmed','rejected')), reason text, reviewed_by uuid REFERENCES accounts(id), submitted_at timestamptz NOT NULL DEFAULT now(), reviewed_at timestamptz);
CREATE UNIQUE INDEX IF NOT EXISTS one_open_payment ON payments(entry_id) WHERE status IN ('submitted','confirmed');
CREATE TABLE IF NOT EXISTS uploads(id uuid PRIMARY KEY, owner_id uuid NOT NULL REFERENCES accounts(id), purpose text NOT NULL CHECK(purpose IN ('proof','poster','avatar')), pathname text NOT NULL, url text NOT NULL, content_type text NOT NULL, payment_id uuid REFERENCES payments(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS refunds(id uuid PRIMARY KEY, entry_id uuid NOT NULL REFERENCES entries(id), amount integer NOT NULL, status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','processed','declined')), reason text NOT NULL, bank_reference text, admin_id uuid REFERENCES accounts(id), created_at timestamptz NOT NULL DEFAULT now(), processed_at timestamptz, UNIQUE(entry_id));
CREATE TABLE IF NOT EXISTS matches(id uuid PRIMARY KEY, category_id uuid NOT NULL REFERENCES categories(id), round integer NOT NULL, position integer NOT NULL, entry_a uuid REFERENCES entries(id), entry_b uuid REFERENCES entries(id), next_match uuid REFERENCES matches(id), next_slot text CHECK(next_slot IN ('a','b')), scheduled_at timestamptz, court text, winner_id uuid REFERENCES entries(id), score jsonb, status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','completed','bye')), version integer NOT NULL DEFAULT 0, UNIQUE(category_id,round,position));
CREATE TABLE IF NOT EXISTS awards(category_id uuid NOT NULL REFERENCES categories(id), athlete_id uuid NOT NULL REFERENCES athletes(id), points integer NOT NULL CHECK(points>=0), placement text NOT NULL, PRIMARY KEY(category_id,athlete_id));
CREATE TABLE IF NOT EXISTS announcements(id uuid PRIMARY KEY, event_id uuid NOT NULL REFERENCES events(id), text text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS notifications(id uuid PRIMARY KEY, account_id uuid NOT NULL REFERENCES accounts(id), text text NOT NULL, read_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS saved_events(account_id uuid NOT NULL REFERENCES accounts(id), event_id uuid NOT NULL REFERENCES events(id), PRIMARY KEY(account_id,event_id));
CREATE TABLE IF NOT EXISTS disputes(id uuid PRIMARY KEY, account_id uuid NOT NULL REFERENCES accounts(id), match_id uuid NOT NULL REFERENCES matches(id), reason text NOT NULL, status text NOT NULL DEFAULT 'open', resolution text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS audit(id uuid PRIMARY KEY, account_id uuid REFERENCES accounts(id), action text NOT NULL, entity_id text NOT NULL, details jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS api_limits(bucket text PRIMARY KEY, count integer NOT NULL, resets_at timestamptz NOT NULL);
CREATE INDEX IF NOT EXISTS category_entries ON entries(category_id,status);
CREATE INDEX IF NOT EXISTS athlete_entries ON entry_members(athlete_id);
CREATE INDEX IF NOT EXISTS event_categories ON categories(event_id);
CREATE INDEX IF NOT EXISTS account_notifications ON notifications(account_id,created_at DESC);

CREATE TABLE IF NOT EXISTS payment_references(reference_hash text PRIMARY KEY, payment_id uuid NOT NULL REFERENCES payments(id));
CREATE TABLE IF NOT EXISTS payment_corrections(id uuid PRIMARY KEY, payment_id uuid NOT NULL REFERENCES payments(id), account_id uuid NOT NULL REFERENCES accounts(id), reason text NOT NULL, status text NOT NULL DEFAULT 'open', resolution text, created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS one_open_correction ON payment_corrections(payment_id) WHERE status='open';
